const DESIGN_APP={views:[]},DESIGN_WEB={routes:[]},DESIGN_LEGAL={};
/* Local chart fixtures and interactions. No product APIs or real purchases. */
const chartPurchases=[
 {day:history.at(-182).day,amount:10000000,initial:true},
 {day:'2026-07-13',amount:10000000},
 {day:'2026-08-17',amount:10000000},
 {day:'2026-09-21',amount:10000000},
];
const chartSampleDays=history.slice(-182);
const chartSampleWeights=chartSampleDays.map((d,i)=>i===0?0:1+(new Date(d.day).getUTCDay()===5?.65:new Date(d.day).getUTCDay()===6?.8:0)+Math.sin(i*.61)*.16);
const chartOlderAmounts=allocate(6000000,chartSampleWeights.slice(0,91));
const chartRecentAmounts=allocate(18800000,chartSampleWeights.slice(91));
chartRecentAmounts[90]=158000;
chartRecentAmounts[89]+=18800000-chartRecentAmounts.reduce((a,b)=>a+b,0);
const chartOwnerAmounts=[...chartOlderAmounts,...chartRecentAmounts];
const chartLocationA=allocate(15800000,chartOwnerAmounts);
chartLocationA[181]=85000;chartLocationA[180]+=15800000-chartLocationA.reduce((a,b)=>a+b,0);
const chartLocationB=chartOwnerAmounts.map((amount,i)=>amount-chartLocationA[i]);
const chartVisits=allocate(1240,chartOwnerAmounts);
chartVisits[181]=5;chartVisits[180]+=1240-chartVisits.reduce((a,b)=>a+b,0);
let chartBought=0,chartUsed=0;
history.forEach((d,i)=>{
 const j=i-(history.length-182),other=d.admin-d.owner;
 const purchases=chartPurchases.filter(p=>p.day===d.day);
 chartBought+=purchases.reduce((n,p)=>n+p.amount,0);
 d.a=j>=0?chartLocationA[j]:0;d.b=j>=0?chartLocationB[j]:0;
 d.owner=d.a+d.b;d.admin=d.owner+other;d.visits=j>=0?chartVisits[j]:0;
 chartUsed+=d.owner;
 Object.assign(d,{used:chartUsed,contracted:chartBought,available:chartBought-chartUsed,purchases});
});

periodData=function(){
 const arr=history.slice(-state.period),prev=history.slice(-state.period*2,-state.period);
 const key=state.location==='a'?'a':state.location==='b'?'b':'owner';
 const face=sum(arr,key),before=sum(prev,key),scale=face/24800000;
 const full=face===24800000&&state.location==='all';
 const visits=state.location==='all'?sum(arr,'visits'):Math.round(face/20000);
 const unique=full?812:Math.min(visits,Math.round(visits*.655));
 const newClients=full?214:Math.round(unique*.264),answered=Math.round(320*scale);
 const yes=Math.round(168*scale),no=Math.round(122*scale);
 return{face,before,visits,unique,newClients,returning:unique-newClients,repeat:full?320:Math.round(unique*.394),tip:Math.round(face*.1),cash:Math.round(face*20/24.8),answered,yes,no,dontKnow:answered-yes-no,scale};
};

chartPoints=function(){
 const n=state.range==='1s'?7:state.range==='1m'?30:state.range==='3m'?91:365;
 const current=history.slice(-n),previous=history.slice(-n*2,-n);
 if(n<=30||state.chart==='credito')return current.map((d,i)=>({...d,previous:previous[i]?.owner||0,long:formatDate(d.day)+' '+new Date(d.day).getUTCFullYear()}));
 function groups(days){
  if(n===91)return Array.from({length:13},(_,i)=>days.slice(i*7,i*7+7));
  const result=[];
  for(const d of days){if(!result.length||result.at(-1)[0].day.slice(0,7)!==d.day.slice(0,7))result.push([]);result.at(-1).push(d);}
  return result.slice(-12);
 }
 const prior=groups(previous);
 return groups(current).map((g,i)=>({...g.at(-1),owner:sum(g,'owner'),previous:sum(prior[i]||[],'owner'),purchases:g.flatMap(d=>d.purchases),label:n===91?formatDate(g[0].day):new Intl.DateTimeFormat('es-CL',{month:'short',timeZone:'UTC'}).format(new Date(g[0].day)),long:n===91?formatDate(g[0].day)+' – '+formatDate(g.at(-1).day)+' 2026':new Intl.DateTimeFormat('es-CL',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(g[0].day))}));
};

const chartTextBase=chartText;
chartText=function(id,i){
 const p=charts[id].points[i];
 return chartTextBase(id,i)+(p.purchases||[]).map(p=>`<span class="chart-purchase-text">${p.initial?'Compra inicial':'Recarga'} · ${formatDate(p.day)}: <b>${clp(p.amount)}</b></span>`).join('');
};

trendChart=function(id,points,sourceSeries,options={}){
 const series=sourceSeries.map(s=>({...s,count:s.count||options.count}));
 const W=window.innerWidth<570?340:660,H=id==='credit'?260:210,L=49,R=12,T=15,B=35;
 const width=W-L-R,height=H-T-B,band=width/Math.max(1,points.length),stacked=series.filter(s=>s.type==='stack');
 const max=Math.max(1,...points.flatMap(p=>series.map(s=>p[s.key]||0)),...points.map(p=>stacked.reduce((n,s)=>n+(p[s.key]||0),0)),options.max||0)*1.08;
 const x=i=>L+band*(i+.5),y=v=>T+height-v/max*height;
 const value=(i,s)=>s.type==='stack'?stacked.slice(0,stacked.indexOf(s)+1).reduce((n,t)=>n+(points[i][t.key]||0),0):(points[i][s.key]||0);
 const barWidth=band*.62/Math.max(1,series.filter(s=>s.type==='bar').length);
 const pointX=(i,s)=>s.type==='bar'?x(i)-series.length*barWidth/2+(series.indexOf(s)+.5)*barWidth:x(i);
 charts[id]={points,series,index:points.length-1,position:points.length-1,pinned:null,key:series[0].key,geometry:{W,H,L,R,T,B,width,height,band,max,x,y,value,pointX}};
 let svg='';
 for(let i=0;i<=4;i++){
  const v=max*i/4;
  svg+=`<line x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}" stroke="#e2e3d7" stroke-dasharray="3 4"/><text x="${L-9}" y="${y(v)+3}" text-anchor="end">${options.count?num(Math.round(v)):v>=1e6?num(v/1e6,1)+' M':v>=1000?num(v/1000,0)+' mil':num(v)}</text>`;
 }
 for(const s of series){
  if(s.type==='stack'){
   const layer=stacked.indexOf(s),lower=p=>stacked.slice(0,layer).reduce((n,t)=>n+(p[t.key]||0),0);
   const upper=points.map((p,i)=>`${i?'L':'M'}${L+i*band},${y(lower(p)+(p[s.key]||0))} H${L+(i+1)*band}`).join(' ');
   const bottom=[...points].reverse().map((p,j)=>{const i=points.length-1-j;return`L${L+(i+1)*band},${y(lower(p))} H${L+i*band}`;}).join(' ');
   svg+=`<path d="${upper} ${bottom} Z" fill="${s.color}" opacity=".9"/>`;
  }else if(s.type==='bar'){
   points.forEach((p,i)=>svg+=`<rect x="${pointX(i,s)-barWidth/2}" y="${y(p[s.key]||0)}" width="${barWidth}" height="${H-B-y(p[s.key]||0)}" rx="2" fill="${s.color}"/>`);
  }else{
   let d=`M${L},${y(value(0,s))} L${x(0)},${y(value(0,s))}`;
   points.slice(1).forEach((p,j)=>{const i=j+1,v=value(i,s),purchase=(p.purchases||[]).reduce((n,p)=>n+p.amount,0);
    if(s.curve==='step')d+=` H${x(i)} V${y(v)}`;
    else if(s.curve==='balance'&&purchase)d+=` L${x(i)},${y(v-purchase)} V${y(v)}`;
    else d+=` L${x(i)},${y(v)}`;
   });
   d+=` L${W-R},${y(value(points.length-1,s))}`;
   if(s.fill)svg+=`<path d="${d} L${W-R},${H-B} L${L},${H-B}Z" fill="${s.color}" opacity=".14"/>`;
   svg+=`<path d="${d}" fill="none" stroke="${s.color}" data-chart-series="${s.key}" stroke-width="${s.width||2}" vector-effect="non-scaling-stroke" ${s.dash?'stroke-dasharray="5 5"':''} stroke-linecap="round" stroke-linejoin="round"/>`;
  }
 }
 points.forEach((p,i)=>{
  if(i===0||i===points.length-1||i%Math.ceil(points.length/5)===0)svg+=`<text x="${x(i)}" y="${H-9}" text-anchor="middle">${esc(p.label)}</text>`;
 });
 svg+=`<rect class="chart-hit" data-chart-surface="${id}" x="${L}" y="${T}" width="${width}" height="${height}" fill="transparent"/><g class="chart-guide" data-chart-guide hidden aria-hidden="true"><rect class="chart-guide-shade"/><line class="chart-guide-line" data-guide-vertical/><line class="chart-guide-line" data-guide-horizontal/><circle class="chart-guide-point" r="4"/></g><circle class="chart-pinned-point" data-chart-pin r="6" hidden aria-hidden="true"/>`;
 const marks=id==='credit'&&points.some(p=>p.purchases?.length);
 return`<div class="chart" data-chart="${id}" tabindex="0" role="group" aria-label="${esc(options.label||'Gráfico')}. Flechas para explorar, Enter para fijar un punto y Escape para soltarlo."><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(options.label||'Gráfico')}">${svg}</svg><div class="chart-hover-label" hidden aria-hidden="true"></div><div class="legend">${series.map(s=>`<span><i style="background:${s.color}"></i>${s.label}</span>`).join('')}</div><div class="chart-explore"><span>Desliza sobre el gráfico o usa las flechas. Haz clic para fijar un punto.</span><button type="button" data-chart-clear="${id}" hidden>Quitar selección</button><span data-chart-selection aria-live="polite"></span></div><div class="chart-tip" id="tip-${id}" aria-live="polite">${chartText(id,points.length-1)}</div><details class="chart-data"><summary>Ver datos del gráfico</summary>${table(['Fecha',...series.map(s=>s.label),...(marks?['Compras / recargas']:[])],points.map(p=>[p.long||p.label,...series.map(s=>s.count?num(p[s.key]||0):clp(p[s.key]||0)),...(marks?[(p.purchases||[]).map(p=>(p.initial?'Compra inicial':'Recarga')+' '+formatDate(p.day)+' · '+clp(p.amount)).join('<br>')||'—']:[])]))}</details></div>`;
};

function chartNode(id){return document.querySelector(`[data-chart="${id}"]`);}
function chartValue(c,position,series){
 const left=Math.floor(position),right=Math.min(c.points.length-1,left+1),t=position-left;
 const a=c.geometry.value(left,series),b=c.geometry.value(right,series);
 if(series.type==='bar'||series.type==='stack')return c.geometry.value(Math.round(position),series);
 if(series.curve==='step')return a;
 const purchase=series.curve==='balance'?(c.points[right].purchases||[]).reduce((n,p)=>n+p.amount,0):0;
 return a+(b-purchase-a)*t;
}
function chartPosition(c,position,key,pointX){
 const series=c.series.find(s=>s.key===key)||c.series[0],index=Math.round(position);
 const x=series.type==='bar'||series.type==='stack'?c.geometry.pointX(index,series):pointX??c.geometry.L+c.geometry.band*(position+.5);
 return{x,y:c.geometry.y(chartValue(c,position,series)),series};
}
function chartReading(c,position){
 const a=Math.floor(position),b=Math.ceil(position),between=b!==a&&c.series.every(s=>s.type!=='bar'&&s.type!=='stack');
 return{between,label:between?formatDate(c.points[a].day)+(c.points[a].day.slice(0,4)!==c.points[b].day.slice(0,4)?' '+c.points[a].day.slice(0,4):'')+' – '+formatDate(c.points[b].day)+' '+c.points[b].day.slice(0,4):c.points[Math.round(position)].long||c.points[Math.round(position)].label};
}
function chartSet(el,attrs){Object.entries(attrs).forEach(([k,v])=>el.setAttribute(k,String(v)));}
function drawChartPoint(id,position,key,pointX){
 const c=charts[id],node=chartNode(id);if(!c||!node)return;
 position=Math.max(0,Math.min(c.points.length-1,position));
 c.position=position;c.index=Math.round(position);c.key=key||c.key;
 const {x,y,series}=chartPosition(c,position,c.key,pointX),g=c.geometry,guide=node.querySelector('[data-chart-guide]');c.pointX=x;
 guide.removeAttribute('hidden');guide.style.setProperty('--chart-color',series.color);
 chartSet(guide.querySelector('rect'),{x:g.L,y,width:Math.max(0,x-g.L),height:Math.max(0,g.H-g.B-y)});
 chartSet(guide.querySelector('[data-guide-vertical]'),{x1:x,x2:x,y1:y,y2:g.H-g.B});
 chartSet(guide.querySelector('[data-guide-horizontal]'),{x1:g.L,x2:x,y1:y,y2:y});
 chartSet(guide.querySelector('circle'),{cx:x,cy:y,fill:series.color});
 const tip=node.querySelector('.chart-hover-label'),reading=chartReading(c,position);tip.hidden=false;
 const rounded=Object.fromEntries(c.series.map(s=>[s.key,Math.round(chartValue(c,position,s))]));
 if(id==='credit'&&'available' in rounded&&'used' in rounded&&'contracted' in rounded)rounded.used=rounded.contracted-rounded.available;
 const rows=c.series.map(s=>`<span class="chart-hover-series ${s.key===series.key?'active':''}" data-hover-series="${esc(s.key)}"><i style="background:${s.color}"></i><span>${esc(s.label)}</span><b>${s.count?num(rounded[s.key]):clp(rounded[s.key])}</b></span>`).join('');
 const purchases=reading.between?[]:c.points[c.index].purchases||[];
 tip.innerHTML=`<strong>${esc(reading.label)}</strong>${reading.between?'<small>Entre cierres diarios · valor aproximado</small>':''}${rows}${purchases.map(p=>`<small class="chart-purchase-text">${p.initial?'Compra inicial':'Recarga'} +${clp(p.amount)}</small>`).join('')}`;
 const svg=node.querySelector('svg'),box=svg.getBoundingClientRect(),matrix=svg.getScreenCTM(),anchor=new DOMPoint(x,y).matrixTransform(matrix),origin=node.getBoundingClientRect();
 const left=anchor.x-box.left+16,flip=left+tip.offsetWidth>box.width;
 const tipX=Math.max(0,Math.min(box.width-tip.offsetWidth,(flip?anchor.x-box.left-tip.offsetWidth-16:left))),anchorX=anchor.x-box.left,anchorY=anchor.y-origin.top;
 tip.style.left=tipX+'px';
 const overlapsPoint=tipX<anchorX+7&&tipX+tip.offsetWidth>anchorX-7;
 const tipY=overlapsPoint?(anchorY>=tip.offsetHeight+14?anchorY-tip.offsetHeight-14:anchorY+14):Math.max(0,Math.min(box.height-tip.offsetHeight,anchorY-tip.offsetHeight/2));
 tip.style.top=tipY+'px';
 const readout=document.getElementById('tip-'+id),readoutKey=c.index+':'+reading.between;
 if(c.readoutKey!==readoutKey){readout.innerHTML=(reading.between?'<span class="muted">Cierre más cercano:</span>':'')+chartText(id,c.index);c.readoutKey=readoutKey;}
 const pin=node.querySelector('[data-chart-pin]'),clear=node.querySelector('[data-chart-clear]'),selection=node.querySelector('[data-chart-selection]');
 if(c.pinned){const p=chartPosition(c,c.pinned.position,c.pinned.key,c.pinned.x);chartSet(pin,{cx:p.x,cy:p.y});pin.style.setProperty('--chart-color',p.series.color);pin.removeAttribute('hidden');clear.hidden=false;selection.textContent='Punto fijado · '+chartReading(c,c.pinned.position).label;}
 else{pin.setAttribute('hidden','');clear.hidden=true;selection.textContent='';}
}
showChartPoint=function(point){const [id,index]=point.split(':');if(charts[id])drawChartPoint(id,Number(index));};
function exploreChart(event,id){
 const node=chartNode(id),c=charts[id];if(!node||!c)return;
 const svg=node.querySelector('svg'),point=new DOMPoint(event.clientX,event.clientY).matrixTransform(svg.getScreenCTM().inverse()),g=c.geometry;
 const px=Math.max(g.L,Math.min(g.W-g.R,point.x)),position=Math.max(0,Math.min(c.points.length-1,(px-g.L)/g.band-.5));
 const candidates=c.series.filter(s=>s.type!=='stack'||s===c.series[0]),distance=s=>Math.abs(chartPosition(c,position,s.key,px).y-point.y);
 const closest=candidates.reduce((a,b)=>distance(b)<distance(a)?b:a),current=candidates.find(s=>s.key===c.key);
 const locked=chartDrag?.chart===c?c.series.find(s=>s.key===chartDrag.key):null;
 const series=locked||(current&&distance(current)<=distance(closest)+5?current:closest);
 drawChartPoint(id,series.type==='bar'||series.type==='stack'?Math.round(position):position,series.key,px);
}
function chartSurface(event){return event.target.closest('.chart svg')?.closest('[data-chart]');}
const chartPending=new Map();let chartFrame=0;
function queueChart(event,id){
 chartPending.set(id,{clientX:event.clientX,clientY:event.clientY,chart:charts[id]});
 if(chartFrame)return;chartFrame=requestAnimationFrame(()=>{chartFrame=0;const entries=[...chartPending];chartPending.clear();for(const [id,event] of entries)if(charts[id]===event.chart)exploreChart(event,id);});
}
function chartFlush(event,id){chartPending.delete(id);exploreChart(event,id);}
function chartRestore(id){
 chartPending.delete(id);const c=charts[id],node=chartNode(id);if(!c||!node)return;
 if(c.pinned)drawChartPoint(id,c.pinned.position,c.pinned.key,c.pinned.x);
 else{node.querySelector('[data-chart-guide]').setAttribute('hidden','');node.querySelector('.chart-hover-label').hidden=true;document.getElementById('tip-'+id).innerHTML=chartText(id,c.points.length-1);c.readoutKey=null;}
}
function pinChartPoint(id,force=false){
 const c=charts[id];if(!c)return;
 if(c.pointX===undefined)c.pointX=chartPosition(c,c.position,c.key).x;
 const same=c.pinned&&c.pinned.key===c.key&&Math.abs(c.pinned.x-c.pointX)<2;
 c.pinned=!force&&same?null:{index:c.index,position:c.position,key:c.key,x:c.pointX};drawChartPoint(id,c.position,c.key,c.pointX);
}
let chartDrag=null,chartSuppressClick=null,chartLastPointer=null;
document.addEventListener('pointerdown',event=>{
 const node=chartSurface(event);if(!node||event.button!==0)return;
 const id=node.dataset.chart,svg=node.querySelector('svg');chartSuppressClick=null;chartLastPointer=null;chartFlush(event,id);
 chartDrag={id,chart:charts[id],key:charts[id].key,pointerId:event.pointerId,x:event.clientX,y:event.clientY,moved:false,touch:event.pointerType==='touch'};
 svg.setPointerCapture(event.pointerId);if(!chartDrag.touch)event.preventDefault();
});
document.addEventListener('pointermove',event=>{
 const node=chartSurface(event),drag=chartDrag?.pointerId===event.pointerId?chartDrag:null,id=drag?.id||node?.dataset.chart;
 if(!id)return;
 if(drag){if(charts[id]!==drag.chart){chartDrag=null;return;}const dx=Math.abs(event.clientX-drag.x),dy=Math.abs(event.clientY-drag.y);if(dx>4||dy>4)drag.moved=true;if(drag.touch&&!drag.moved)return;}
 queueChart(event,id);
});
document.addEventListener('pointerup',event=>{
 const drag=chartDrag;if(!drag||drag.pointerId!==event.pointerId)return;
 if(charts[drag.id]!==drag.chart){chartDrag=null;return;}
 chartFlush(event,drag.id);chartDrag=null;
 const c=charts[drag.id];chartLastPointer={id:drag.id,position:c.position,key:c.key,x:c.pointX,clientX:event.clientX,clientY:event.clientY,until:performance.now()+500};
 if(drag.moved){pinChartPoint(drag.id,true);chartSuppressClick={id:drag.id,until:performance.now()+500};}
 const svg=chartNode(drag.id)?.querySelector('svg');if(svg?.hasPointerCapture(event.pointerId))svg.releasePointerCapture(event.pointerId);
});
document.addEventListener('pointercancel',event=>{if(chartDrag?.pointerId===event.pointerId){const id=chartDrag.id;chartDrag=null;chartRestore(id);}});
document.addEventListener('pointerout',event=>{
 const svg=event.target.closest('.chart svg');if(!svg||svg.contains(event.relatedTarget)||chartDrag)return;chartRestore(svg.closest('[data-chart]').dataset.chart);
});
document.addEventListener('click',event=>{
 const clear=event.target.closest('[data-chart-clear]');
 if(clear){event.stopImmediatePropagation();const id=clear.dataset.chartClear,c=charts[id];c.pinned=null;drawChartPoint(id,c.position,c.key,c.pointX);chartNode(id).focus({preventScroll:true});return;}
 const node=chartSurface(event);if(!node)return;
 event.stopImmediatePropagation();const id=node.dataset.chart;
 if(chartSuppressClick?.id===id&&performance.now()<chartSuppressClick.until){chartSuppressClick=null;return;}
 // Compatibility clicks round coordinates; retain the precise pointer-up position.
 if(chartLastPointer?.id===id&&performance.now()<chartLastPointer.until&&Math.hypot(event.clientX-chartLastPointer.clientX,event.clientY-chartLastPointer.clientY)<2)drawChartPoint(id,chartLastPointer.position,chartLastPointer.key,chartLastPointer.x);
 else chartFlush(event,id);
 chartLastPointer=null;pinChartPoint(id);node.focus({preventScroll:true});
},true);
document.addEventListener('keydown',event=>{
 const node=event.target.closest('[data-chart]');if(!node||event.target.closest('button,summary,a'))return;
 const id=node.dataset.chart,c=charts[id];if(!c)return;
 if(['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();event.stopImmediatePropagation();const i=event.key==='Home'?0:event.key==='End'?c.points.length-1:Math.max(0,Math.min(c.points.length-1,c.index+(event.key==='ArrowLeft'?-1:1)));chartPending.delete(id);drawChartPoint(id,i);}
 if(event.key==='Enter'||event.key===' '){event.preventDefault();event.stopImmediatePropagation();pinChartPoint(id);}
 if(event.key==='Escape'&&c.pinned){event.preventDefault();event.stopImmediatePropagation();c.pinned=null;drawChartPoint(id,c.position,c.key,c.pointX);}
},true);

creditChart=function(){
 const points=chartPoints(),consumption=state.chart==='consumo';
 const controls=`<div class="actions"><div class="segmented" role="group" aria-label="Vista del gráfico">${['credito','consumo'].map(v=>`<button data-chart-view="${v}" class="${state.chart===v?'selected':''}" aria-pressed="${state.chart===v}">${v==='credito'?'Crédito':'Consumo'}</button>`).join('')}</div><label class="sr-only" for="chart-range">Rango del gráfico</label><select class="select" id="chart-range" data-control="chart-range">${[['1s','1 semana'],['1m','1 mes'],['3m','3 meses'],['12m','12 meses']].map(([v,l])=>`<option value="${v}" ${state.range===v?'selected':''}>${l}</option>`).join('')}</select></div>`;
 const purchases=points.flatMap(p=>p.purchases||[]);
 const events=purchases.length?`<div class="chart-purchases">${purchases.map(p=>`<span>${p.initial?'Compra inicial':'Recarga'} · ${formatDate(p.day)} <b>+${clp(p.amount)}</b></span>`).join('')}</div>`:'';
 return card(consumption?'Tu consumo en el tiempo':'Tu crédito en el tiempo',consumption?'Consumo por tramo comparado con el período anterior':'Saldos diarios · las recargas aumentan lo comprado y lo disponible',trendChart('credit',points,consumption?[{key:'owner',label:'Consumo del período',color:'#18332c',type:'bar'},{key:'previous',label:'Período anterior',color:'#c4caba',type:'bar'}]:[{key:'available',label:'Disponible',color:'#18332c',curve:'balance'},{key:'used',label:'Consumido',color:'#ef684e'},{key:'contracted',label:'Comprado',color:'#88937d',curve:'step',dash:true}],{label:consumption?'Consumo y período anterior':'Evolución del crédito comprado, consumido y disponible'})+events+'<p class="small muted block">Historia de ejemplo desde abril de 2026 · Reservado: $0 · Vencido: $0. Las compras de lotes y recargas son datos ilustrativos.</p>',controls);
};
const chartCreditViewBase=creditView;
creditView=function(){
 const rows=[];
 for(const [company,usedTotal] of [['De Street',15800000],['Pistacho',9000000]]){
  let remainingUsed=usedTotal;
  chartPurchases.forEach((p,i)=>{const used=Math.min(5000000,remainingUsed);remainingUsed-=used;const expires=new Date(p.day);expires.setUTCFullYear(expires.getUTCFullYear()+1);rows.push([`L-${company==='De Street'?'DS':'PI'}-${String(i+1).padStart(3,'0')} · ${company}`,formatDate(p.day)+' 2026 / '+formatDate(expires)+' 2027',clp(5000000),clp(2750000),clp(used),clp(5000000-used),badge(used===5000000?'Agotado':'Activo',used===5000000?'neutral':'')]);});
 }
 const html=chartCreditViewBase(),marker='<div class="block"><section class="card "><div class="card-head"><div><h2>Lotes de consumo</h2>';
 const start=html.indexOf(marker);
 if(start<0)throw new Error('Missing owner lot table');
 return html.slice(0,start).replace('Valor de consumo inicial','Compra inicial y tres recargas')+`<div class="block">${card('Lotes de consumo','Compra inicial y tres recargas, separadas por sociedad.',table(['Lote / sociedad','Compra / vence','Consumo comprado','Pago anticipado','Consumido','Disponible','Estado'],rows)+'<p class="notice">Pedir más crédito envía una solicitud para evaluar otra compra de consumo. El saldo no aumenta al enviar el formulario.</p>')}</div>`;
};
views.dueno.credito=creditView;
const chartAdminSummaryBase=views.admin.panel;
views.admin.panel=()=>chartAdminSummaryBase().replace('Últimos 60 días · el ejemplo empieza el 6 de septiembre.','Últimos 60 días · actividad de ejemplo desde abril.');

