const designCatalog=[];
const designState={variant:'principal',forms:{},role:'dueno',pos:'justo',billStep:0,deviceLinked:false};
const W='';
const page=()=>'';
const ui=()=>'';
const designField=(label,name,value='',type='text',options=null,required=true)=>`<label class="design-field"><span>${esc(label)}</span>${options?`<select name="${name}" class="select" ${name==='provider'?'data-design-control="pos"':''}>${options.map(v=>`<option ${v===value?'selected':''}>${esc(v)}</option>`).join('')}</select>`:type==='textarea'?`<textarea name="${name}" rows="4" ${required?'required':''}>${esc(value)}</textarea>`:`<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'min="0" step="1"':''} ${type==='password'?'autocomplete="new-password"':''}>`}</label>`;
const designCheck=(label,name,checked=false)=>`<label class="check-label"><input type="checkbox" name="${name}" ${checked?'checked':''}>${esc(label)}</label>`;
const designForm=(id,fields,label='Revisar cambios de ejemplo',sub='')=>`<form class="design-form" data-design-form="${id}"><div class="design-fields">${fields}</div>${sub?`<p class="notice">${sub}</p>`:''}<div class="form-feedback" role="status"></div><div class="actions"><button type="submit" class="btn">${label}</button><button type="reset" class="btn light">Restablecer</button></div></form>`;
const designTabs=(routes)=>`<nav class="design-tabs" aria-label="Secciones">${routes.map(([route,label])=>link(route,label,state.mode+'/'+state.view===route?'btn':'btn light')).join('')}</nav>`;
const merchantTabs=()=>designTabs([['admin/marca','Marca'],['admin/condiciones','Condiciones'],['admin/sociedades','Sociedades'],['admin/lotes','Lotes'],['admin/locales','Locales'],['admin/horarios','Horarios'],['admin/pos','Caja / POS'],['admin/accesos','Accesos']]);
function registerDesign(mode,id,title,sources,render,states=['principal','carga','vacio','error'],note=''){
 if(!views[mode])views[mode]={};views[mode][id]=render;designCatalog.push({mode,id,title,sources,states,note});
}
function designHero(title,subtitle,photo=ASSETS.cover){return `<section class="design-hero"><img src="${photo}" alt="${esc(title)}"><div><div class="eyebrow">Vamo’a · ejemplo de diseño</div><h2>${esc(title)}</h2><p>${esc(subtitle)}</p></div></section>`;}
function designList(ts,mode='caja'){return table(['Precuenta / mesa','Consumo','Propina','Cobro al comensal','Caja',''],ts.map(t=>[`<strong>${esc(t.tab)}</strong><br><span class="small muted">Mesa ${t.table} · ${esc(t.local)} · ${t.time}</span>`,clp(t.face),clp(t.tip),clp(t.charged),badge(t.status==='closed'?'Cerrada':'Por cerrar',t.status==='closed'?'':'warn'),btn('Ver cuenta','design-caja-detail',t.id,'text-link')]));}
