function legalDesign(kind){const titles={terminos:'Términos de Vamo’a.',privacidad:'Tus datos, con claridad.',datos:'Qué datos guardamos.'};const sections=kind==='terminos'?['Qué es Vamo’a','Tu cuenta y requisitos','Pagar por precuenta','Créditos y vencimientos','Propina','Devoluciones y soporte','Contenido de la comunidad']:kind==='privacidad'?['Quién es responsable','Qué guardamos y para qué','Tarjetas y proveedores','Tu perfil y tus notas','Cuánto tiempo guardamos datos','Tus derechos y cómo pedirlos']:['Inscripción al lanzamiento','Cuenta y autenticación','Pagos y créditos','Restaurantes y turnos','Fotos y comunidad','Avisos y medición de uso'];return head(titles[kind],'Diseño editorial. La redacción completa y vigente se conserva en la fuente indicada en el índice.','Público · Información')+`<div class="design-legal"><aside class="card"><div class="eyebrow">En esta página</div>${sections.map((t,i)=>`<a href="#legal-${i}" data-legal-section="${i}">${esc(t)}</a>`).join('')}<div class="actions">${link('publico/terminos','Términos')}${link('publico/privacidad','Privacidad')}${link('publico/datos','Inventario de datos')}</div></aside><article class="card">${sections.map((t,i)=>`<section id="legal-${i}" class="design-legal-section"><div class="eyebrow">${String(i+1).padStart(2,'0')}</div><h2>${esc(t)}</h2>${kind==='datos'?table(['Dato','Para qué','Base / duración'],[['Ejemplo de estructura','Prestar el servicio','Según categoría en la fuente']]):`<p class="muted">Bloque editorial del documento existente. Este diseño define tipografía, ancho de lectura, índice y navegación; el texto legal completo se obtiene de la página fuente, sin introducir nuevas condiciones.</p>`}</section>`).join('')}<p class="notice">hola@vamoa.cl · canal de contacto del producto.</p></article></div>`;}
for(const id of ['terminos','privacidad','datos'])registerDesign('publico',id,({terminos:'Términos',privacidad:'Privacidad',datos:'Inventario de datos'})[id],[page(id==='datos'?'privacidad/datos':id)],()=>legalDesign(id),['principal']);
