function designStateView(entry,variant){const messages={vacio:['Todavía no hay registros.','La lista se llenará cuando exista información para los filtros y el contexto elegidos.'],error:['No pudimos cargar la información.','Revisa tu conexión y vuelve a intentar. Los cambios que estabas escribiendo deben conservarse.'],revocado:['Esta caja perdió el acceso.','Pide al dueño un código nuevo para vincular este navegador al local.'],invalido:['Revisa el código.','El código no es válido o ya se utilizó. Pide uno nuevo al dueño.'],vencido:['Este enlace o código venció.','Vuelve al paso de origen y solicita uno nuevo.'],bloqueado:['Por ahora no puedes continuar.','Revisa las condiciones del local o vuelve a ingresar para obtener un desafío nuevo.'],cancelado:['La operación se canceló.','Puedes volver al paso anterior para intentarlo cuando quieras.'],app:['Continúa en la app.','Esta cuenta es de comensal. Se usa desde la app, sin portal web.'],'no-encontrado':['No encontramos este registro.','Revisa el enlace o vuelve al listado para elegir otro.'],'sin-permiso':['Este rol no tiene acceso.','El dueño puede ver negocio y equipo; el encargado opera y ve historial; el cajero atiende el turno y los cierres.'],'no-habilitado':['Este local no recibe reservas por Vamo’a.','Sin acuerdo y habilitación no se presenta un botón para reservar. La propuesta usa un comercio de prueba.'],'no-compatible':['Este navegador no ofrece esa opción.','Ingresa con contraseña y tu segundo factor.'],incierto:['Estamos confirmando el pago.','Consulta la operación original. No vuelvas a cobrar mientras no haya un resultado definitivo.'],rechazado:['El pago fue rechazado.','Este resultado es definitivo. Puedes cambiar de tarjeta e intentar un pago nuevo.'],'cuenta-cambio':['La cuenta cambió en la caja.','Revisa el detalle actualizado antes de confirmar el pago.'],abierta:['Crisp aún muestra la cuenta abierta.','Registra consumo y propina, cierra en la caja y vuelve a verificar.'],diferencia:['Los importes no coinciden.','Revisa número de cuenta, local, consumo completo, propina y medio Vamo’a antes de confirmar.'],cerrada:['Cierre verificado.','La cuenta sale de pendientes; Vamo’a leyó un cierre consistente.'],devuelta:['Esta cuenta tiene una devolución.','El comprobante conserva el detalle original y el estado de devolución.'],historico:['Cuenta histórica con código.','Este estado conserva el recorrido anterior de validación por código; no reemplaza el pago nuevo por precuenta.'],baja:['Ya no te escribimos.','Se conserva tu inscripción y baja para respetar tu elección. Puedes volver a suscribirte.'],listo:['Listo.','El resultado quedó confirmado en esta muestra de diseño. No se ejecutó ninguna operación real.']};if(variant==='principal')return '';if(variant==='carga')return `<section class="card design-state" aria-label="Cargando"><div class="skeleton"></div><div class="skeleton"></div><div class="skeleton small"></div><p>Cargando ${esc(entry.title.toLowerCase())}…</p></section>`;const [title,text]=variant==='guardando'?['Guardando…','La acción queda bloqueada mientras esperamos el resultado.']:variant==='verificando'?['Releyendo la cuenta en Crisp…','No se retira de pendientes hasta recibir un cierre consistente.']:(messages[variant]||['Estado de diseño',variant]);return `<section class="card design-state"><div class="eyebrow">${esc(entry.title)}</div><h2 class="display">${title}</h2><p class="muted">${text}</p><div class="actions">${btn('Volver a la vista','design-reset-state','','btn')}${['app','historico'].includes(variant)?'<a class="btn light" href="guia/app.html">Ver documento de la app</a>':''}${variant==='revocado'||variant==='invalido'?link('caja/vincular','Vincular caja'):''}</div></section>`;}

const publicRoles=['dueno','encargado','cajero','caja','admin'];
const publicEntries=designCatalog.filter(s=>publicRoles.includes(s.mode));
designCatalog.splice(0,designCatalog.length,...publicEntries);
for(const mode of Object.keys(views))if(!publicRoles.includes(mode))delete views[mode];
designModes.splice(0,designModes.length,...designModes.filter(([mode])=>publicRoles.includes(mode)||mode==='documento'));
views.documento={indice:()=>{
 const q=(state.search['design-index']||'').toLocaleLowerCase('es');
 const entries=publicEntries.filter(s=>(s.title+' '+s.mode+' '+s.id).toLocaleLowerCase('es').includes(q));
 return head('Cada rol, su vista.','Prototipo de diseño con datos ilustrativos. Las acciones cambian sólo la muestra.','Portales de Vamo’a',`<a class="btn" href="guia/">Guía para marketing ↗</a>`)+`<div class="grid cols-3">${kpi('Paneles',String(publicEntries.length),'Dueño, encargado, cajero, caja y admin','dark')}${kpi('Roles','5','Navegación por contexto','lime')}${kpi('Estados',String(publicEntries.reduce((n,s)=>n+s.states.length-1,0)),'Carga, vacío, error y resultados')}</div><div class="block">${card('Encuentra una vista','Busca por tarea, nombre o rol.',`<label class="sr-only" for="design-search">Buscar un panel</label><input id="design-search" class="search" data-search="design-index" placeholder="Ej. crédito, cierre, equipo, consultas…" value="${esc(state.search['design-index']||'')}">`+table(['Rol','Vista','Variantes'],entries.map(s=>[esc(designModes.find(([mode])=>mode===s.mode)[1]),link(s.mode+'/'+s.id,esc(s.title),'text-link'),esc(s.states.join(' · '))])))}</div><p class="notice">Cifras y personas de ejemplo. El rediseño aún no está llevado al producto. Este prototipo no procesa pagos, envía invitaciones ni escribe en la caja del restaurante.</p>`;
}};
designNav.documento=[['Revisar',[navItem('indice','Índice de los portales','book')]]];

const renderBeforeDesign=render;
render=function(){renderBeforeDesign();const modeTitle=designModes.find(m=>m[0]===state.mode)[1];const nav=designNav[state.mode];document.getElementById('sidebar').innerHTML=`<a href="#${state.mode}/${Object.keys(views[state.mode])[0]}" aria-label="Inicio de ${esc(modeTitle)}"><img class="brand" src="${ASSETS.brand}" alt="Vamo’a"></a><div class="context">${['dueno','encargado','cajero','caja'].includes(state.mode)?`<img class="restaurant-logo" src="${ASSETS.decalle}" alt="De Calle">`:'<div class="avatar">VA</div>'}<div><strong class="small">${['dueno','encargado','cajero','caja'].includes(state.mode)?'De Calle':'Vamo’a'}</strong><div class="eyebrow" style="font-size:8px">${esc(modeTitle)}</div></div></div><nav>${nav.map(([t,items])=>`<div class="eyebrow nav-title">${esc(t)}</div>${items.map(([id,t,glyph])=>`<a class="nav-link ${state.view===id?'active':''}" href="#${state.mode}/${id}" ${state.view===id?'aria-current="page"':''}>${icon(glyph)}<span>${esc(t)}</span></a>`).join('')}`).join('')}</nav><div class="sidebar-bottom"><a class="design-doc-link" href="#documento/indice">${icon('book')} Índice completo del diseño</a><p style="margin-top:10px">Prototipo de diseño · datos de ejemplo</p></div>`;document.getElementById('top-avatar').textContent=state.mode==='admin'?'VA':'DC';document.title=modeTitle+' · '+state.view+' · Vamo’a';const selector=document.getElementById('design-mode');if(selector)selector.value=state.mode;const content=document.getElementById('content');const entry=designCatalog.find(s=>s.mode===state.mode&&s.id===state.view);if(entry){const variant=entry.states.includes(designState.variant)?designState.variant:'principal';const toolbar=`<div class="design-toolbar"><strong>${entry.mode==='propuestas'?'Propuesta · no implementada':'Revisión de diseño'}</strong><span>Estado</span><select data-design-control="state" aria-label="Estado de la vista">${entry.states.map(v=>`<option value="${v}" ${v===variant?'selected':''}>${esc(v)}</option>`).join('')}</select><details><summary>Alcance</summary><p>Referencia de diseño con datos de ejemplo. Las operaciones son simuladas.</p></details></div>`;if(variant!=='principal')content.innerHTML=toolbar+designStateView(entry,variant);else content.insertAdjacentHTML('afterbegin',toolbar);}
 // Restricted roles: remove owner-only exports, invitations and finance links.
 if(state.mode==='encargado'||state.mode==='cajero'){content.querySelectorAll('[data-action="export-tx"],[data-action="export-owner"],[data-action="more-credit"],[data-action="invite"]').forEach(e=>e.remove());content.querySelectorAll('a[href^="#dueno/"]').forEach(a=>{const id=a.hash.split('/')[1];if(views[state.mode][id])a.href='#'+state.mode+'/'+id;else a.remove();});}
 if(location.protocol==='file:')content.querySelectorAll('a[href]').forEach(a=>{const raw=a.getAttribute('href');if(raw.startsWith('app.html'))a.setAttribute('href',raw.replace('app.html','Vamo’a App · Rediseño.html'));else if(/^(index|parati|restaurantes|contacto)\.html/.test(raw))a.setAttribute('href','Vamo’a Web/'+raw);});
 if(state.mode==='caja'){content.querySelectorAll('[data-action="transaction"]').forEach(e=>e.remove());}
};
const navigateBeforeDesign=navigate;
navigate=function(){let [mode,id,variant,billId]=(location.hash.slice(1)||'dueno/resumen').split('/');if(mode==='appweb'){mode='documento';id='archivo';variant='';billId='';}if(billId)designState.billId=billId;if(!views[mode])mode='dueno';if(!views[mode][id])id=Object.keys(views[mode])[0];designState.variant=variant||'principal';if(location.hash!=='#'+mode+'/'+id+(variant?'/'+variant:'')+(billId?'/'+billId:''))window.history.replaceState(null,'','#'+mode+'/'+id+(variant?'/'+variant:'')+(billId?'/'+billId:''));navigateBeforeDesign();};
window.addEventListener('hashchange',navigate);
const initialModes=document.querySelector('[data-mode]').parentElement;
initialModes.innerHTML=`<label class="sr-only" for="design-mode">Contexto del diseño</label><select id="design-mode" class="design-selector" data-design-control="mode">${designModes.filter(([id])=>['dueno','encargado','cajero','caja','admin','documento'].includes(id)).map(([id,t])=>`<option value="${id}">${t}</option>`).join('')}</select>`;
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.designControl==='mode')location.hash=t.value+'/'+Object.keys(views[t.value])[0];if(t.dataset.designControl==='state'){designState.variant=t.value;window.history.replaceState(null,'','#'+state.mode+'/'+state.view+(t.value==='principal'?'':'/'+t.value));render();}if(t.dataset.designControl==='pos'){designState.pos=t.value;render();}});
Object.assign(actions,{
 'design-retry-reply':()=>toast('Se revisó el reenvío de la misma respuesta. No se envió correo.'),
 'design-archive-reply':()=>toast('Consulta archivada en la simulación, sin enviar una respuesta.'),
 'design-caja-detail':id=>{designState.billId=id;location.hash='caja/cuenta/principal/'+id;},
 'design-reset-state':()=>{designState.variant='principal';window.history.replaceState(null,'','#'+state.mode+'/'+state.view);render();},
 help:()=>modal('Recorre todo Vamo’a.',`<p class="small">El selector cambia entre roles, caja, administración, sus paneles. Estado permite revisar las variantes de cada vista. El índice permite encontrar los paneles por tarea y rol.</p><p class="notice">Las operaciones son simulaciones locales. Recargar restablece la muestra. Las acciones de este prototipo usan datos ilustrativos.</p><div class="actions">${link('documento/indice','Abrir índice completo','btn')}<a class="btn light" href="guia/app.html">Documento de la app</a></div>`),
 'design-sound':()=>{designState.sound=!designState.sound;render();toast('Sonido '+(designState.sound?'activado':'apagado')+' en la muestra.');},
 'design-passkey':()=>modal('Autenticación de ejemplo.',`<p class="small">El navegador real presenta su diálogo de huella, rostro o código del dispositivo. Aquí sólo se revisa el estado.</p><div class="actions">${link('admin/panel','Entrar a administración de ejemplo','btn')}${btn('Cancelar','dismiss')}</div>`),
 'design-resend-invite':()=>toast('Invitación revisada en la muestra. No se envió correo.'),
 'design-unsubscribe':()=>{designState.variant='baja';render();},'design-resubscribe':()=>{designState.variant='listo';render();},
 'design-receipt':()=>modal('Tu comprobante.',`<p class="small">Compartir un PDF o enviarlo al correo de la cuenta. Es un comprobante de pago; la emisión tributaria va por separado.</p><div class="actions">${btn('Revisar envío de ejemplo','design-send-receipt','','btn')}${btn('Cerrar','dismiss')}</div>`),
 'design-defer-passkey':()=>modal('Puedes activarla después.',`<p>Está en Administración → Seguridad. Si guardar la preferencia falla, la invitación vuelve.</p><div class="actions">${link('admin/seguridad','Ver Seguridad','btn')}${btn('Cerrar','dismiss')}</div>`),
 'design-send-receipt':()=>{dismiss();toast('Envío simulado. No se envió un correo.');},
 'design-logout':()=>{location.hash='acceso/ingresar';},'design-revoke':()=>toast('Revocación revisada en la muestra.')
});
document.addEventListener('submit',e=>{const f=e.target;if(!f.dataset.designForm)return;e.preventDefault();if(!f.checkValidity()){f.reportValidity();return;}const d=Object.fromEntries(new FormData(f)),id=f.dataset.designForm;const error=msg=>f.querySelector('.form-feedback').textContent=msg;
 if(id==='proposal-capacity'&&(!Number.isSafeInteger(Number(d.capacity))||Number(d.capacity)<1||Number(d.party)<1||Number(d.party)>Number(d.capacity))){error('Usa cupos enteros positivos y un máximo por reserva que no supere la capacidad.');return;}
 if(id==='proposal-news'){if(!d.reviewed){error('Revisa el destino, el contenido y el consentimiento antes de continuar.');return;}modal('Revisión de envío de ejemplo.',metrics([['Categoría',esc(d.category)],['Título',esc(d.title)],['Audiencia con consentimiento','86'],['Push elegible','72'],['Excluidas sin consentimiento','34']])+`<p class="notice">El emisor está pendiente. No se mandaron avisos ni se validó una audiencia real.</p>${btn('Volver a editar','dismiss','','btn')}`);return;}
 if(id==='proposal-image'){const file=f.querySelector('[name="image"]').files[0];if(!file||!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>3*1024*1024){error('Elige una imagen JPG, PNG o WebP de hasta 3 MB. La validación real debe comprobar los bytes en el servidor.');return;}if(!d.rights){error('Confirma la autorización de uso antes de revisar esta foto.');return;}modal('Foto lista para revisar.',metrics([['Archivo',esc(file.name)],['Uso',esc(d.usage)],['Texto alternativo',esc(d.alt)]])+`<p class="notice">No se subió el archivo. La interfaz propuesta debe verificar los bytes, retirar metadatos y evitar duplicados con el servidor.</p>${btn('Volver','dismiss','','btn')}`);return;}
 if(id==='close-caja'){if(!d.closed){error('Primero registra los importes y cierra la cuenta en Crisp.');return;}if(d.outcome!=='Cierre correcto'){error(d.outcome==='Cuenta abierta'?'La cuenta sigue abierta en la lectura de ejemplo.':d.outcome==='Importes distintos'?'Consumo, propina o medio de pago no coinciden.':'No pudimos consultar la caja. La cuenta sigue pendiente.');return;}const t=transactions.find(t=>t.id===(f.dataset.transaction||'VM-3816'));t.status='closed';render();toast('Cierre de ejemplo confirmado. No se escribió en Crisp.');return;}
 if(id==='verify-caja'){const t=transactions.find(t=>t.tab===d.tab&&t.local==='Plaza Egaña');if(!t){error('No hay un pago confirmado para esta precuenta en este local hoy.');return;}designState.billId=t.id;location.hash='caja/cuenta/principal/'+t.id;return;}
 if(id==='link-caja'){if(!/^DEMO[A-Z0-9]{4}$/.test(d.code)){error('Usa DEMOEGAN para revisar el recorrido de ejemplo.');return;}designState.deviceLinked=true;location.hash='caja/hoy';return;}
 if(id==='verify-email'){designState.variant='listo';render();toast('Correo confirmado en la muestra. Continúa en la app.');return;}
 if(id==='login'){location.hash='acceso/mfa';return;}if(id==='mfa'){if(!/^\d{6}$/.test(d.code)&&!d.code.startsWith('DEMO-')){error('Usa seis dígitos o un recuperador de ejemplo.');return;}location.hash='dueno/resumen';return;}if(id==='mfa-setup'){location.hash='acceso/recuperadores';return;}if(id==='recovery-codes'){if(!d.saved){error('Confirma que guardaste los códigos antes de seguir.');return;}location.hash='dueno/resumen';return;}
 if(['reset'].includes(id)){if(d.password.length<10||!/[a-z]/i.test(d.password)||!/\d/.test(d.password)){error('Usa al menos 10 caracteres, una letra y un número.');return;}if(d.confirm&&d.confirm!==d.password){error('Las contraseñas deben coincidir.');return;}}
 if(id==='dispute'&&(Number(d.amount)>19800||Number(d.amount)<=0)){error('El importe de contracargo debe ser positivo y no superar $19.800.');return;}
 if(id==='refund-full'){const amount=Number(d.amount),tip=Number(d.tip);if(amount<=0||amount>19800||tip>3000||tip>amount||tip<0||amount-tip>16800){error('La devolución debe respetar el cargo original: $16.800 de consumo y $3.000 de propina.');return;}}
 if(id==='terms'&&Number(d.minBillClp)>Number(d.maxBillClp)){error('La cuenta mínima no puede superar la máxima.');return;}
 if(id==='company'&&(Number(d.ratio)<30||Number(d.ratio)>80)){error('El factor de adquisición del formulario debe estar entre 30% y 80%.');return;}
 if(id==='lot-full'){if(Number(d.face)<=0||Number(d.cash)<=0||Number(d.cash)>Number(d.face)){error('Consumo y pago deben ser positivos; el pago no puede superar el valor facial.');return;}if(d.validity==='Fecha fija'&&!d.expiresAt){error('Indica el último día de uso para una vigencia de fecha fija.');return;}}
 const safe=Object.entries(d).filter(([key])=>!/password|token|secret|apiKey|bankAccountNumber/i.test(key));modal('Resultado listo para revisar.',`<section class="card">${metrics(safe.map(([key,value])=>[esc(key),esc(value)]))}</section><p class="notice">Formulario ${esc(id)} · simulación local. No envía correos, guarda cambios en el producto, factura ni mueve dinero.</p><div class="actions">${btn('Volver al formulario','dismiss','','btn')}</div>`);});
document.addEventListener('click',e=>{const a=e.target.closest('[data-legal-section]');if(!a)return;e.preventDefault();document.getElementById('legal-'+a.dataset.legalSection)?.scrollIntoView({behavior:'smooth',block:'start'});});
window.vamoaDesignPortals={catalog:designCatalog,views:Object.fromEntries(Object.entries(views).map(([mode,map])=>[mode,Object.keys(map)])),web:DESIGN_WEB,app:DESIGN_APP};
